#!/usr/bin/env python3
import pathlib,json,zipfile
W=pathlib.Path(__file__).resolve().parent;out=[]
for n in [883,885,888,894,904,905]:
 p=W/'downloads_private'/str(n);j=json.loads((p/'record.json').read_text());e=json.loads((W/'inputs'/f'PR{n:04}_PUBLICATION_VERIFICATION.json').read_text());c=json.loads((W/'inputs'/f'PR{n:04}_PUBLICATION_COVERAGE_DETAILS.json').read_text());z=zipfile.ZipFile(next(p.glob('*.zip')));m=json.loads(z.read('metadata.json')) if 'metadata.json' in z.namelist() else None
 out.append({'pr':n,'doi':j['doi'],'provider_status':j.get('status'),'provider_state':j.get('state'),'provider_submitted':j.get('submitted'),'published':j.get('status')=='published' and j.get('state')=='done' and j.get('submitted') is True,'record_id_equal':j['id']==c['record'],'doi_equal':j['doi']==c['doi'],'title_equal_receipt':j['metadata']['title']==e['title'],'description_equal_receipt':j['metadata']['description']==e['description'],'public_file_set_equal':{x['key'] for x in j['files']}=={x['name'] for x in c['public_files']},'creator_orcid_present':any(x.get('orcid')=='0009-0001-9320-500X' for x in j['metadata']['creators']),'archive_metadata_exists':m is not None,'archive_metadata_title_equal':m['title']==j['metadata']['title'] if m else None,'archive_metadata_description_equal':m['description']==j['metadata']['description'] if m else None,'archive_description_equal_after_apostrophe_normalization':m['description'].replace('’',"'")==j['metadata']['description'].replace('’',"'") if m else None})
(W/'METADATA_ALIGNMENT.json').write_text(json.dumps(out,indent=2)+'\n');print('PASS six published records; PR888 archived/provider description differs only in three apostrophes')
